#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_H 1000
#define MAX_W 1000

int H, W, K;
char grid[MAX_H][MAX_W+1];
int dist[MAX_H][MAX_W];
int dh[] = {-1, 1, 0, 0}; // north, south, east, west
int dw[] = {0, 0, 1, -1};

typedef struct {
    int h, w;
} Point;

Point queue[MAX_H * MAX_W];
int front, back;

void enqueue(int h, int w) {
    queue[back].h = h;
    queue[back].w = w;
    back++;
}

Point dequeue() {
    return queue[front++];
}

int is_empty() {
    return front == back;
}

int main() {
    int x1, y1, x2, y2;
    scanf("%d %d %d", &H, &W, &K);
    scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
    x1--; y1--; x2--; y2--; // zero-index

    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
    }

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            dist[i][j] = INT_MAX;
        }
    }

    dist[x1][y1] = 0;
    front = back = 0;
    enqueue(x1, y1);

    while (!is_empty()) {
        Point p = dequeue();
        int h = p.h;
        int w = p.w;
        int d = dist[h][w];

        if (h == x2 && w == y2) {
            printf("%d\n", d);
            return 0;
        }

        for (int dir = 0; dir < 4; dir++) {
            for (int step = 1; step <= K; step++) {
                int nh = h + dh[dir] * step;
                int nw = w + dw[dir] * step;

                if (nh < 0 || nh >= H || nw < 0 || nw >= W) break;
                if (grid[nh][nw] == '@') break;
                if (dist[nh][nw] < d + 1) break; // already visited with equal or better

                if (dist[nh][nw] > d + 1) {
                    dist[nh][nw] = d + 1;
                    enqueue(nh, nw);
                }
            }
        }
    }

    printf("-1\n");
    return 0;
}

