#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int x, y;
} Node;

int main(void) {
    int H, W, K;
    if (scanf("%d %d %d", &H, &W, &K) != 3) return 0;

    char **grid = (char **)malloc(H * sizeof(char *));
    for (int i = 0; i < H; i++) {
        grid[i] = (char *)malloc((W + 1) * sizeof(char));
        scanf("%s", grid[i]);
    }

    int x1, y1, x2, y2;
    scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
    x1--; y1--; x2--; y2--;

    const int INF = 1e9;
    int *dist = (int *)malloc(H * W * sizeof(int));
    for (int i = 0; i < H * W; i++) dist[i] = INF;

    Node *queue = (Node *)malloc(H * W * sizeof(Node));
    int head = 0, tail = 0;

    dist[x1 * W + y1] = 0;
    queue[tail++] = (Node){x1, y1};

    int dx[4] = {-1, 0, 1, 0};
    int dy[4] = {0, 1, 0, -1};

    while (head < tail) {
        Node cur = queue[head++];
        int cx = cur.x, cy = cur.y;
        int cd = dist[cx * W + cy];

        for (int dir = 0; dir < 4; dir++) {
            for (int step = 1; step <= K; step++) {
                int nx = cx + dx[dir] * step;
                int ny = cy + dy[dir] * step;

                if (nx < 0 || nx >= H || ny < 0 || ny >= W) break;
                if (grid[nx][ny] == '@') break;

                int nid = nx * W + ny;

                if (dist[nid] < cd + 1) break;
                if (dist[nid] == cd + 1) continue;

                dist[nid] = cd + 1;
                queue[tail++] = (Node){nx, ny};
            }
        }
    }

    int ans = dist[x2 * W + y2];
    if (ans == INF) ans = -1;
    printf("%d\n", ans);

    for (int i = 0; i < H; i++) free(grid[i]);
    free(grid);
    free(dist);
    free(queue);

    return 0;
}

