public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt();
        int W = sc.nextInt();
        int K = sc.nextInt();
        int x1 = sc.nextInt() - 1;
        int y1 = sc.nextInt() - 1;
        int x2 = sc.nextInt() - 1;
        int y2 = sc.nextInt() - 1;

        char[][] grid = new char[H][W];
        for (int i = 0; i < H; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Distance array: -1 means unvisited
        int[][] dist = new int[H][W];
        for (int[] row : dist) Arrays.fill(row, -1);

        // BFS using deque for 0-1 BFS (though here all steps cost 1, but we use deque for efficiency)
        Deque<int[]> dq = new ArrayDeque<>();
        dist[x1][y1] = 0;
        dq.addLast(new int[]{x1, y1});

        int[] dx = {0, 0, 1, -1};
        int[] dy = {1, -1, 0, 0};

        while (!dq.isEmpty()) {
            int[] cur = dq.pollFirst();
            int x = cur[0], y = cur[1];
            int curDist = dist[x][y];

            if (x == x2 && y == y2) {
                System.out.println(curDist);
                return;
            }

            // Explore in all four directions
            for (int dir = 0; dir < 4; dir++) {
                // Move step by step up to K squares
                for (int step = 1; step <= K; step++) {
                    int nx = x + dx[dir] * step;
                    int ny = y + dy[dir] * step;

                    // Out of bounds or blocked
                    if (nx < 0 || nx >= H || ny < 0 || ny >= W || grid[nx][ny] == '@') {
                        break;
                    }

                    // If already visited with a smaller or equal distance, no need to continue further in this direction
                    if (dist[nx][ny] != -1 && dist[nx][ny] <= curDist) {
                        // If visited with same distance, we can still continue further because we might reach new cells
                        // But if visited with strictly smaller distance, we can break because further cells would also have smaller or equal distance
                        if (dist[nx][ny] < curDist) {
                            break;
                        }
                        // If equal distance, continue to further cells
                        continue;
                    }

                    // If not visited or visited with larger distance, update and add to queue
                    if (dist[nx][ny] == -1 || dist[nx][ny] > curDist + 1) {
                        dist[nx][ny] = curDist + 1;
                        dq.addLast(new int[]{nx, ny});
                    }
                }
            }
        }

        System.out.println(-1);
    }
}

