        dist[sr][sc2] = 0;
        queue.add(new int[]{sr, sc2});

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0], c = cur[1];

            if (r == er && c == ec) {
                System.out.println(dist[r][c]);
                return;
            }

            for (int d = 0; d < 4; d++) {
                for (int step = 1; step <= K; step++) {
                    int nr = r + dr[d] * step;
                    int nc = c + dc[d] * step;
                    if (nr < 0 || nr >= H || nc < 0 || nc >= W) break;
                    if (grid[nr][nc] == '@') break;
                    if (dist[nr][nc] == -1) {
