import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Pair {
        int x, y;
        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int H = fs.nextInt();
        int W = fs.nextInt();
        int K = fs.nextInt();

        int x1 = fs.nextInt() - 1;
        int y1 = fs.nextInt() - 1;
        int x2 = fs.nextInt() - 1;
        int y2 = fs.nextInt() - 1;

        char[][] grid = new char[H][];
        for (int i = 0; i < H; i++) {
            grid[i] = fs.next().toCharArray();
        }

        int INF = 1 << 29;
        int[][] dist = new int[H][W];
        for (int i = 0; i < H; i++) Arrays.fill(dist[i], INF);

        ArrayDeque<Pair> q = new ArrayDeque<>();
        dist[x1][y1] = 0;
        q.add(new Pair(x1, y1));

        int[] dx = {-1, 0, 1, 0};
        int[] dy = {0, 1, 0, -1};

        while (!q.isEmpty()) {
            Pair cur = q.poll();
            int cx = cur.x, cy = cur.y;
            int cd = dist[cx][cy];

            for (int dir = 0; dir < 4; dir++) {
                for (int step = 1; step <= K; step++) {
                    int nx = cx + dx[dir] * step;
                    int ny = cy + dy[dir] * step;

                    if (nx < 0 || nx >= H || ny < 0 || ny >= W) break;
                    if (grid[nx][ny] == '@') break;

                    if (dist[nx][ny] < cd + 1) break;
                    if (dist[nx][ny] == cd + 1) continue;

                    dist[nx][ny] = cd + 1;
                    q.add(new Pair(nx, ny));
                }
            }
        }

        System.out.println(dist[x2][y2] == INF ? -1 : dist[x2][y2]);
    }
}
